#!/usr/bin/env python3
"""Register the proved adelic CM image and its exact remaining scope."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'notes/pbc_results.json'
rows=json.loads(p.read_text())
new=[
dict(id='C.20',statement='The full positive adelic CM image is the product of the normalized norm-one tori; its parity kernel has exactly the arithmetic image',status='Proved',where_proved='sections/C.tex',depends_on='C.12; C.13; R24 E.58 and E.65; LozanoRobledo2022 Cor3.4/3.7; MilneCM2007 Thm3.10',answers='Task C.7; Task C.8; Task C.9; Lead 11; Lead 25',notes='Single global signs and modulo-two normalization retained. Individual projective CM images fill the factors by Weber reciprocity and the unit-mod2 isomorphism. Arithmetic joint image has index2; E58 fills its other coset. Image on Cphi still exactly the dichotomy C21.'),
dict(id='C.21',statement='GT and descent-fixed positive CM images have exactly two possibilities; Delta is the unique nonarithmetic character through the two coordinates',status='Proved',where_proved='sections/C.tex',depends_on='C.20; C.1; R24 character extension',answers='Task C.7; Task C.8; Task C.9; Lead 25',notes='Each image is either the Galois index-two fiber product or the whole normalized product, according to the unresolved Delta restriction. Every finite-order character factoring through these CM coordinates and vanishing on Galois is0 orDelta; no claim about all characters of GT0.'),
dict(id='C.22',statement='Separate arithmeticity of both CM coordinates does not imply zero parity',status='Refuted',where_proved='sections/C.tex',depends_on='C.20; R24 E.58',answers='Task C.11; Lead 27(b)',notes='E58 has Delta1 but each coordinate is individually realized adelically by some G_Qab element. Therefore the two proposed separate-coordinate Lattes equivalences plus joint zero-parity implication cannot all be true. Does not decide the individual commutation equivalences.')]
ids={r['id']:r for r in rows}
for r in new:
    if r['id'] in ids:ids[r['id']].update(r)
    else:rows.append(r)
ids['C.7']['notes']='Full GT0 positive adelic image and parity-kernel image now proved C20. Exact two-choice Cphi image C21; actual choice, manuscript scalar/frame identifications and descent consequences remain open.'
ids['C.9']['notes']='All full-group characters remain open. C21 proves the exact subspace of characters factoring through the two adelic CM coordinates is generated by Delta; changing their finite modulus cannot create another.'
ids['C.11']['notes']='Individual geometric Lattes commutation criteria remain open. C22 refutes the conjunction of both separate arithmetic-coordinate equivalences with the claimed joint Delta0 implication.'
p.write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
print('Registered CM rows; total',len(rows))
